import 'dart:typed_data';

/// Match result for two fingerprints generated by the same algorithm version.
class StudioAudioFingerprintMatch {
  const StudioAudioFingerprintMatch({
    required this.matchedLandmarks,
    required this.queryLandmarks,
    required this.referenceLandmarks,
    required this.offsetFrames,
    required this.offsetMs,
    required this.queryCoverage,
    required this.referenceCoverage,
    required this.confidence,
    this.matchedQueryTimestampsMs = const [],
    this.matchedReferenceTimestampsMs = const [],
  });

  final int matchedLandmarks;
  final int queryLandmarks;
  final int referenceLandmarks;
  final int offsetFrames;
  final int offsetMs;
  final double queryCoverage;
  final double referenceCoverage;
  final double confidence;
  final List<int> matchedQueryTimestampsMs;
  final List<int> matchedReferenceTimestampsMs;

  bool get isMatch => matchedLandmarks >= 8 && confidence >= 0.12;
}

/// Correlates spectral peak landmarks by frequency bin and temporal offset.
///
/// This is a local candidate matcher, not proof of ownership. It is intended
/// for recordings generated by the same algorithm version and sample profile.
class StudioAudioFingerprintMatcher {
  const StudioAudioFingerprintMatcher({
    this.hopSize = 1024,
    this.sampleRate = 11025,
  });

  final int hopSize;
  final int sampleRate;

  StudioAudioFingerprintMatch compare({
    required Uint8List query,
    required Uint8List reference,
  }) {
    final queryRecords = _decode(query);
    final referenceRecords = _decode(reference);
    if (queryRecords.isEmpty || referenceRecords.isEmpty) {
      return _empty(queryRecords.length, referenceRecords.length);
    }

    final referenceFramesByBin = <int, List<int>>{};
    for (final record in referenceRecords) {
      referenceFramesByBin.putIfAbsent(record.bin, () => <int>[]).add(record.frame);
    }

    final votes = <int, int>{};
    for (final record in queryRecords) {
      final referenceFrames = referenceFramesByBin[record.bin];
      if (referenceFrames == null) continue;
      for (final referenceFrame in referenceFrames) {
        final offset = referenceFrame - record.frame;
        votes.update(offset, (value) => value + 1, ifAbsent: () => 1);
      }
    }

    if (votes.isEmpty) return _empty(queryRecords.length, referenceRecords.length);
    final ranked = votes.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    final bestOffset = ranked.first.key;

    final matchedQueryLandmarks = <(int, int)>{};
    final matchedReferenceLandmarks = <(int, int)>{};
    for (final record in queryRecords) {
      final frames = referenceFramesByBin[record.bin];
      if (frames == null) continue;
      if (frames.any((frame) => frame - record.frame == bestOffset)) {
        matchedQueryLandmarks.add((record.frame, record.bin));
        matchedReferenceLandmarks.add((record.frame + bestOffset, record.bin));
      }
    }

    final matched = matchedQueryLandmarks.length;
    final queryCoverage = matched / queryRecords.length;
    final referenceCoverage = matchedReferenceLandmarks.length / referenceRecords.length;
    final denominator = queryRecords.length + referenceRecords.length;
    final confidence = denominator == 0 ? 0.0 : (2 * matched / denominator);

    return StudioAudioFingerprintMatch(
      matchedLandmarks: matched,
      queryLandmarks: queryRecords.length,
      referenceLandmarks: referenceRecords.length,
      offsetFrames: bestOffset,
      offsetMs: (bestOffset * hopSize * 1000 / sampleRate).round(),
      queryCoverage: queryCoverage,
      referenceCoverage: referenceCoverage,
      confidence: confidence,
      matchedQueryTimestampsMs: matchedQueryLandmarks
          .map((landmark) => landmark.$1)
          .toSet()
          .map((frame) => (frame * hopSize * 1000 / sampleRate).round())
          .toList()..sort(),
      matchedReferenceTimestampsMs: matchedReferenceLandmarks
          .map((landmark) => landmark.$1)
          .toSet()
          .map((frame) => (frame * hopSize * 1000 / sampleRate).round())
          .toList()..sort(),
    );
  }

  StudioAudioFingerprintMatch _empty(int queryCount, int referenceCount) =>
      StudioAudioFingerprintMatch(
        matchedLandmarks: 0,
        queryLandmarks: queryCount,
        referenceLandmarks: referenceCount,
        offsetFrames: 0,
        offsetMs: 0,
        queryCoverage: 0,
        referenceCoverage: 0,
        confidence: 0,
      );

  List<_Landmark> _decode(Uint8List bytes) {
    if (bytes.isEmpty) return const <_Landmark>[];
    if (bytes.length % 8 != 0) {
      throw const FormatException('Fingerprint artifact has an invalid record length.');
    }
    final data = ByteData.sublistView(bytes);
    final records = <_Landmark>[];
    for (var offset = 0; offset < bytes.length; offset += 8) {
      records.add(
        _Landmark(
          frame: data.getUint32(offset, Endian.little),
          bin: data.getUint16(offset + 4, Endian.little),
        ),
      );
    }
    return records;
  }
}

class _Landmark {
  const _Landmark({required this.frame, required this.bin});
  final int frame;
  final int bin;
}
